// Build one Caption-Pack API job per selected platform.
// Tone 'Auto' resolves to a per-platform default:
// X -> bold, LinkedIn -> professional, Instagram -> warm.
const input = $input.first().json;
const source = String(input['Source'] || '').slice(0, 600);
const audience = String(input['Audience'] || 'general audience');
const countRaw = parseInt(input['Count per platform'] || '3', 10);
const count = Math.min(Math.max(isNaN(countRaw) ? 3 : countRaw, 1), 10);
const toneChoice = String(input['Tone'] || 'Auto (per-platform default)');
const platformChoice = String(input['Platforms'] || 'All three (X + LinkedIn + Instagram)');

const all = ['x', 'linkedin', 'instagram'];
let wanted;
if (platformChoice.startsWith('All three')) wanted = all;
else if (platformChoice.startsWith('X ')) wanted = ['x'];
else if (platformChoice.startsWith('LinkedIn')) wanted = ['linkedin'];
else if (platformChoice.startsWith('Instagram')) wanted = ['instagram'];
else wanted = all;

const toneDefaults = { x: 'bold', linkedin: 'professional', instagram: 'warm' };
const tone = toneChoice.startsWith('Auto') ? null : toneChoice;

return wanted.map((platform) => ({
  json: {
    topic: source,
    audience: audience,
    platform: platform,
    tone: tone || toneDefaults[platform],
    count: count,
    include_hashtags: true
  }
}));

// Collect each platform's caption pack after the loop finishes.
// Incoming (one item per platform): the /v1/caption-pack response
// { pack_id, topic, audience, tone, platform, captions: [{hook, body, cta, hashtags[]}], credits_used, credits_remaining }
const byPlatform = {};
for (const item of $input.all()) {
  const p = item.json || {};
  const plat = p.platform || 'unknown';
  byPlatform[plat] = p;
}
return Object.entries(byPlatform).map(([platform, p]) => ({
  json: {
    platform: platform,
    tone: p.tone || '',
    pack_id: p.pack_id || '',
    captions: p.captions || [],
    credits_used: p.credits_used || 0
  }
}));

// Compile every platform's captions into one markdown posting plan.
// Packs come from the 'Collect Packs' node; balance is this node's input.
const packs = $('Collect Packs').all().map((i) => i.json);
const balance = $input.first().json || {};
const remaining = balance.credits_remaining ?? balance.balance ?? balance.credits ?? 'unknown';

const platformNames = { x: 'X', linkedin: 'LinkedIn', instagram: 'Instagram' };
const order = ['linkedin', 'x', 'instagram'];
const tag = (h) => '#' + String(h).replace(/^#+/, '');

let md = '# Your multi-platform content plan\n';
let totalUsed = 0;
for (const plat of order) {
  const pack = packs.find((p) => p.platform === plat);
  if (!pack) continue;
  totalUsed += pack.credits_used || 0;
  md += `\n## ${platformNames[plat] || plat} (${pack.tone})\n`;
  (pack.captions || []).forEach((c, i) => {
    const tags = (c.hashtags || []).map(tag).join(' ');
    md += `\n--- Caption ${i + 1} ---\n${c.hook || ''}\n\n${c.body || ''}\n\n${c.cta || ''}\n\n${tags}\n`;
  });
}
md += `\n---\nCredits used this run: ${totalUsed} · Remaining: ${remaining}\n`;
md += `Suggested posting order: LinkedIn (morning) → X (midday) → Instagram (evening).`;

return [{
  json: {
    plan: md,
    platforms: packs.map((p) => p.platform),
    credits_used: totalUsed,
    credits_remaining: remaining
  }
}];
